% Ingest Telemetry Data
data = readtable('telemetry_raw.csv'); % or 'telemetry_raw.csv'

% 1. Extract columns by index (Column 1 = Time/Timestamp, Column 2 = Throttle, Column 3 = Temp)
raw_time = data{:, 1};
throttle = data{:, 2};
temp     = data{:, 3};

% 2. Normalize time vector to start at 0 seconds
if max(raw_time) > 100
    % Values are in milliseconds (e.g., 1000, 1050), convert to seconds
    time_sec = (raw_time - raw_time(1)) / 1000;
else
    % Values are already in seconds
    time_sec = raw_time - raw_time(1);
end

% Format data as 2-column matrices: [Time, Signal]
throttle_signal = [time_sec, double(throttle)];
temp_signal     = [time_sec, double(temp)];

% 3. Plot the telemetry traces
figure('Color', 'w'); %[output:207e98f0]
subplot(2,1,1); %[output:207e98f0]
plot(time_sec, throttle, 'b-', 'LineWidth', 1.8); %[output:207e98f0]
ylabel('Throttle Demand (%)', 'FontWeight', 'bold'); %[output:207e98f0]
grid on; %[output:207e98f0]
title('Vehicle Telemetry Acquisition & Fault Latch Trace'); %[output:207e98f0]

subplot(2,1,2); %[output:207e98f0]
plot(time_sec, temp, 'r-', 'LineWidth', 1.8); %[output:207e98f0]
hold on; %[output:207e98f0]
yline(92.0, '--k', 'Trip Threshold (92°C)', 'LineWidth', 1.5); %[output:207e98f0]
ylabel('Accumulator Temp (°C)', 'FontWeight', 'bold'); %[output:207e98f0]
xlabel('Time (seconds)', 'FontWeight', 'bold'); %[output:207e98f0]
grid on; %[output:207e98f0]

